package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamLocalGovBank2 {
  private const val T = "විමධ්‍යගත පාලනය, පළාත් සභා හා පළාත් පාලන ආයතන"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("ශ්‍රී ලංකාවේ වර්තමානයේ ක්‍රියාත්මක වන පළාත් පාලන ආයතන වර්ග තුන කවරේද?", "මහ නගර සභා, නගර සභා සහ ප්‍රාදේශීය සභා", "දිසා සභා, කෝරළ සභා සහ පළාත් සභා", "ගම්සභා, සුළු නගර සභා සහ සෙනෙට් සභා", "දිස්ත්‍රික් සභා, ආණ්ඩු සභා සහ සමථ සභා", "නාගරික, අර්ධ නාගරික හා ග්‍රාමීය ප්‍රදේශ පාලනය සඳහා මෙම පළාත් පාලන ආයතන වර්ග තුන පවතී."),
    q("වැඩි ජනගහනයක් හා ඉහළ නාගරීකරණයක් ඇති ප්‍රධාන නගර පාලනය සඳහා පිහිටුවා ඇති ඉහළම පළාත් පාලන ආයතනය කුමක්ද?", "මහ නගර සභාව", "නගර සභාව", "ප්‍රාදේශීය සභාව", "ග්‍රාම නිලධාරී කාර්යාලය", "කොළඹ, මහනුවර, ගාල්ල වැනි විශාල නගර සඳහා 1947 ආඥාපනත යටතේ මහ නගර සභා ස්ථාපිත කර ඇත."),
    q("මහ නගර සභාවක දේශපාලන නායකයා හෙවත් ප්‍රධානියා හඳුන්වනු ලබන්නේ කුමන තනතුරකින්ද?", "නගරාධිපති (Mayor)", "ප්‍රාදේශීය සභා සභාපති", "දිස්ත්‍රික් ලේකම්", "පළාත් ආණ්ඩුකාර", "මහ නගර සභාවේ සභා රැස්වීම් මෙහෙයවන ප්‍රධාන තේරී පත්වූ නියෝජිතයා නගරාධිපතිවරයාය."),
    q("මහ නගර සභාවක ප්‍රධාන පරිපාලන රාජ්‍ය නිලධාරියා ලෙස කටයුතු කරන්නේ කවුද?", "නාගරික කොමසාරිස් (Municipal Commissioner)", "නාගරික ලේකම්", "ග්‍රාම නිලධාරී", "දිසාපතිවරයා", "මහ නගර සභාවේ සේවක පාලනය හා තීරණ ක්‍රියාත්මක කිරීම නාගරික කොමසාරිස්වරයා අතින් සිදුවේ."),
    q("නගර සභාවක (Urban Council) සහ ප්‍රාදේශීය සභාවක ප්‍රධාන පරිපාලන නිලධාරියා හඳුන්වන්නේ කුමන නමින්ද?", "ලේකම් (Secretary)", "නාගරික කොමසාරිස්", "ප්‍රධාන අමාත්‍ය", "විගණකාධිපති", "මහ නගර සභාවේ කොමසාරිස් සිටින අතර නගර සභා හා ප්‍රාදේශීය සභාවල ප්‍රධාන නිලධාරියා ලේකම්වරයාය."),
    q("නගර සභාවක හෝ ප්‍රාදේශීය සභාවක තේරී පත්වන ප්‍රධානියා හැඳින්වෙන නිල නාමය කුමක්ද?", "සභාපති (Chairman)", "නගරාධිපති", "ආණ්ඩුකාර", "කථානායක", "මහ නගර සභාවේ නගරාධිපති සිටින අතර නගර සභාවල හා ප්‍රාදේශීය සභාවල ප්‍රධානියා සභාපතිවරයා වේ."),
    q("ශ්‍රී ලංකාවේ ප්‍රාදේශීය සභා පද්ධතිය පිහිටුවන ලද්දේ කුමන පනත මඟින්ද?", "1987 අංක 15 දරන ප්‍රාදේශීය සභා පනත", "1939 නගර සභා ආඥාපනත", "1947 මහ නගර සභා ආඥාපනත", "1978 ආණ්ඩුක්‍රම ව්‍යවස්ථාව", "ගම්සභා හා සුළු නගර සභා වෙනුවට 1987 අංක 15 පනතින් ප්‍රාදේශීය සභා ස්ථාපිත කෙරිණි."),
    q("පළාත් පාලන ආයතනයක සාමාන්‍ය නිල කාල සීමාව වසර කීයක්ද?", "අවුරුදු 4", "අවුරුදු 6", "අවුරුදු 2", "අවුරුදු 10", "මහ නගර සභා, නගර සභා හා ප්‍රාදේශීය සභාවල සාමාන්‍ය නිල කාලය වසර 4කි (වසර 1කින් දිගු කළ හැක)."),
    q("පළාත් පාලන ආයතන අතුරින් ග්‍රාමීය ප්‍රදේශවල පාලනය හා සේවා සැපයීම සිදුකරන ආයතනය කුමක්ද?", "ප්‍රාදේශීය සභාව", "මහ නගර සභාව", "නගර සභාව", "ශ්‍රේෂ්ඨාධිකරණය", "විශාල ග්‍රාමීය හා අර්ධ නාගරික ප්‍රදේශ ගණනාවක් ආවරණය කරමින් ප්‍රාදේශීය සභා ක්‍රියාත්මක වේ."),
    q("1865 මහ නගර සභා ආඥාපනත යටතේ බ්‍රිතාන්‍ය පාලන සමයේ ශ්‍රී ලංකාවේ පිහිටවූ ප්‍රථම මහ නගර සභා දෙක මොනවාද?", "කොළඹ සහ මහනුවර", "ගාල්ල සහ යාපනය", "අනුරාධපුර සහ මාතර", "බදුල්ල සහ රත්නපුර", "1865 ආඥාපනත යටතේ 1866 දී කොළඹ සහ මහනුවර ප්‍රථම මහ නගර සභා ආරම්භ කෙරිණි."),
    q("පුරාණ ශ්‍රී ලංකාවේ රජ දවස සිට ගමේ පොදු කටයුතු හා කෘෂි වාරිමාර්ග පාලනය කළ සාම්ප්‍රදායික ග්‍රාමීය ආයතනය කුමක්ද?", "ගම්සභාව", "සෙනෙට් සභාව", "කච්චේරිය", "දිසා අධිකරණය", "ගමේ සුළු ආරවුල් විසඳීම හා වැව් අමුණු රැකීම සිදු කළ ගම්සභා ක්‍රමය 1871 දී බ්‍රිතාන්‍යයන් විධිමත් කළේය."),
    q("පළාත් පාලන ආයතනයක ප්‍රධාන ආදායම් මාර්ගයක් වන 'වරිපනම් බදු' (Assessment Tax) අය කරනු ලබන්නේ කුමක් මතද?", "නිවාස හා වාණිජ දේපළවල වාර්ෂික වටිනාකම මත", "පුද්ගලයාගේ විභාග සුදුසුකම් මත", "විදේශ ගමන් බලපත්‍ර ගාස්තු මත", "රේගු ආනයන භාණ්ඩ මත", "නාගරික හා දියුණු ප්‍රදේශවල ඉඩම් හා ගොඩනැගිලි හිමියන්ගෙන් වරිපනම් බදු අය කෙරේ."),
    q("පළාත් පාලන ආයතනයක් විසින් කුඹුරු හා වගා ඉඩම් ආශ්‍රිතව ප්‍රාදේශීය සභා සීමාවේ අය කරන බද්දක් කුමක්ද?", "අක්කර බද්ද", "රේගු බද්ද", "එකතු කළ අගය මත බද්ද (VAT)", "විදේශ විනිමය බද්ද", "ප්‍රාදේශීය සභා පනත යටතේ හෙක්ටයාර පහට වැඩි වගා ඉඩම්වලින් අක්කර බද්ද අය කිරීමට විධිවිධාන ඇත."),
    q("තම බල ප්‍රදේශය තුළ පවත්වාගෙන යන කඩසාප්පු, හෝටල් හා ව්‍යාපාරික ස්ථානවලින් පළාත් පාලන ආයතන වාර්ෂිකව අය කරන්නේ කුමක්ද?", "වෙළඳ බලපත්‍ර ගාස්තු", "ආදායම් බදු", "ගුවන් තොටුපළ බදු", "විශ්‍රාම වැටුප් ගාස්තු", "සෞඛ්‍යාරක්ෂිත හා නීත්‍යානුකූල ව්‍යාපාර පවත්වාගැනීමට වෙළඳ බලපත්‍ර ලබාගැනීම අනිවාර්යය."),
    q("ප්‍රදේශයේ ඉඩම් හා නිවාස විකුණන විට අය කරන මුද්දර ගාස්තු (Stamp Duty) අවසානයේ හිමිවන්නේ කාටද?", "පළාත් සභා හරහා අදාළ පළාත් පාලන ආයතනවලට", "අභියාචනාධිකරණයට", "ශ්‍රී ලංකා ක්‍රිකට් ආයතනයට", "මැතිවරණ කොමිසමට", "දේපළ පැවරීමේ මුද්දර ගාස්තු ආදායම ප්‍රාදේශීය සංවර්ධනය සඳහා පළාත් පාලන ආයතනවලට පැවරේ."),
    q("පළාත් පාලන ආයතන විසින් සපයනු ලබන ප්‍රධාන මහජන සෞඛ්‍ය සේවාවක් වන්නේ පහත සඳහන් කුමක්ද?", "කැළි කසළ කළමනාකරණය හා කානු පද්ධති පිරිසිදු කිරීම", "විදේශ ගමන් බලපත්‍ර නිකුත් කිරීම", "ජාතික විභාග පැවැත්වීම", "විශ්වවිද්‍යාල උපාධි පිරිනැමීම", "නගර හා ගම් පිරිසිදුව තැබීම, අපද්‍රව්‍ය ඉවත් කිරීම හා මදුරු මර්දනය මූලික රාජකාරි වේ."),
    q("පළාත් පාලන ආයතනයක් විසින් තම ප්‍රදේශයේ පරිසරය හා මහජන ආරක්ෂාව වෙනුවෙන් පවත්වාගෙන යන සේවාවක් කුමක්ද?", "වීදි ලාම්පු දැල්වීම හා අතුරු මාර්ග නඩත්තුව", "ජාත්‍යන්තර මුහුදු සීමා රැකීම", "රේගු බදු පැනවීම", "මහ බැංකු පොලී තීරණය කිරීම", "අභ්‍යන්තර පාරවල් තැනීම, වීදි ආලෝකකරණය හා පොදු වෙළඳපොළ පවත්වාගැනීම පළාත් පාලන කාර්යයන්ය."),
    q("දරුවන්ගේ මුල් ළමාවිය අධ්‍යාපනය හා ප්‍රජා කියවීමේ පුරුදු දියුණු කිරීමට පළාත් පාලන ආයතන පවත්වාගෙන යන්නේ මොනවාද?", "පෙරපාසල් සහ මහජන පුස්තකාල", "වෛද්‍ය විද්‍යාල සහ නීති විද්‍යාල", "ජාතික කෞතුකාගාර සහ තාරකාගාර", "ගුවන් හමුදා පුහුණු පාසල්", "බොහෝ මහ නගර සභා, නගර සභා හා ප්‍රාදේශීය සභා පෙරපාසල්, ළමා උද්‍යාන හා පුස්තකාල පවත්වාගෙන යයි."),
    q("පළාත් පාලන ආයතනයක් සතු මාතෘ හා ළමා සායන, ආයුර්වේද බෙහෙත් ශාලා මඟින් ප්‍රධාන වශයෙන් සිදු කෙරෙන්නේ කුමක්ද?", "ප්‍රාථමික සෞඛ්‍ය සේවා හා රෝග නිවාරණ කටයුතු", "හදවත් සැත්කම්", "විදේශ වෛද්‍ය උපාධි පිරිනැමීම", "ඖෂධ අපනයනය කිරීම", "ගැබිනි මව්වරුන්ට හා ළදරුවන්ට සෞඛ්‍ය උපදෙස් හා ප්‍රාථමික ප්‍රතිකාර ලබාදීම මෙම සායනවලින් සිදුවේ."),
    q("පළාත් පාලන ආයතන විසින් තම බල ප්‍රදේශය තුළ නව නිවසක් හෝ ව්‍යාපාරික ගොඩනැගිල්ලක් ඉදිකිරීමට පෙර ලබාගත යුතු අනුමැතිය කුමක්ද?", "ගොඩනැගිලි සැලසුම් අනුමැතිය (Building Plan Approval)", "විදේශ කටයුතු අමාත්‍යාංශ බලපත්‍රය", "මැතිවරණ කොමිසමේ අවසරය", "විගණකාධිපති සහතිකය", "සැලසුම්ගත නගර නිර්මාණය හා ජල බැස්ම ආරක්ෂා කිරීම සඳහා සැලසුම් අනුමැතිය අනිවාර්ය වේ."),
    q("පළාත් පාලන ආයතනයක් තම බල ප්‍රදේශයට අදාළව සම්මත කරගන්නා ප්‍රාදේශීය නීති රීති හඳුන්වන්නේ කුමන නමින්ද?", "අතුරු ව්‍යවස්ථා (By-laws)", "ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධන", "පාර්ලිමේන්තු පනත්", "ජාත්‍යන්තර ගිවිසුම්", "කසළ බැහැර කිරීම, වෙළඳපොළ පාලනය හා වීදි වෙළඳාම නියාමනයට සභාව විසින් අතුරු ව්‍යවස්ථා සාදයි."),
    q("මහ නගර සභාවක්, නගර සභාවක් හෝ ප්‍රාදේශීය සභාවක් ඉදිරිපත් කරන අතුරු ව්‍යවස්ථා වලංගු වීමට කාගේ අනුමැතිය අවශ්‍ය වේද?", "පළාත් සභාවේ පළාත් පාලන විෂය භාර අමාත්‍යවරයාගේ", "ශ්‍රේෂ්ඨාධිකරණ අගවිනිසුරුගේ", "තේරීම් භාර නිලධාරියාගේ", "පොලිස්පතිවරයාගේ", "අදාළ පළාත් පාලන අමාත්‍යවරයාගේ අනුමැතිය ලැබී රජයේ ගැසට් පත්‍රයේ පළ කළ පසු අතුරු ව්‍යවස්ථා බලාත්මක වේ."),
    q("පළාත් පාලන ආයතනයක සේවක වැටුප් හා විශාල සංවර්ධන ව්‍යාපෘති සඳහා මධ්‍යම රජය හෝ පළාත් සභාව ලබාදෙන මුදල් කවරේද?", "රාජ්‍ය ප්‍රතිපාදන හා ආධාර (Grants)", "රහස් පරිත්‍යාග", "විදේශ විනිමය බදු", "අධිකරණ දඩ මුදල් පමණක්", "තමන් උපයන වරිපනම් ආදායමට අමතරව වැටුප් හා මහා පරිමාණ ව්‍යාපෘති සඳහා රජයේ ප්‍රතිපාදන ලැබේ."),
    q("පළාත් පාලන ආයතනයක 'ප්‍රධාන වගකීම්' අතර පොදු සුසාන භූමි, පොදු ක්‍රීඩාංගණ, වීදි පහන් හා පොදු ළිං නඩත්තුව අයත් වන්නේ කුමන කාණ්ඩයටද?", "පොදු උපයෝගිතා සහ සුබසාධන සේවා", "ජාතික ආරක්ෂක කටයුතු", "විදේශ තානාපති සේවා", "අභියාචනා අධිකරණ සේවා", "ප්‍රජාවගේ දෛනික ජන ජීවිතය පහසු කරන මූලික පොදු පහසුකම් මෙම ආයතනවලින් පවත්වාගෙන යයි."),
    q("ප්‍රාදේශීය සභාවක හෝ නගර සභාවක මාසික සභා රැස්වීම්වලට පැමිණීමේදී පනවා ඇති සභික විනය නීතිය කුමක්ද?", "නිවාඩු නොමැතිව අඛණ්ඩව රැස්වීම් තුනකට නොපැමිණියහොත් සභික ධුරය අහිමි වීම", "මාසිකව දඩ මුදලක් ගෙවීම", "සභාපතිවරයා ඉවත් වීම", "සභාව සම්පූර්ණයෙන් වසා දැමීම", "මහජන නියෝජිතයන්ගේ වගකීම තහවුරු කිරීමට අඛණ්ඩව රැස්වීම් 3ක් මඟහැරීමෙන් සභිකත්වය අහෝසි වේ."),
    q("පළාත් පාලන ආයතනවල කටයුතු පරිපාලන වශයෙන් අධීක්ෂණය කිරීම සඳහා සෑම පළාතකම පිහිටුවා ඇති තනතුර කුමක්ද?", "පළාත් පාලන කොමසාරිස් (Commissioner of Local Government)", "දිස්ත්‍රික් විනිසුරු", "රේගු අධ්‍යක්ෂ ජනරාල්", "පාර්ලිමේන්තු මහ ලේකම්", "පළාත් සභා යටතේ පළාත් පාලන කොමසාරිස්වරයා නගර හා ප්‍රාදේශීය සභාවල කටයුතු සම්බන්ධීකරණය හා අධීක්ෂණය කරයි."),
    q("සිනමාශාලා, සංගීත ප්‍රසංග හා සැණකෙළි වැනි ප්‍රදර්ශනවලින් ප්‍රවේශපත්‍ර මත පළාත් පාලන ආයතන අය කරන බද්ද කුමක්ද?", "විනෝද බද්ද (Entertainment Tax)", "ආනයන රේගු බද්ද", "උප්පැන්න බද්ද", "ආදායම් බද්ද", "පළාත් පාලන බල ප්‍රදේශයේ පැවැත්වෙන මහජන විනෝදාස්වාද කටයුතුවලින් විනෝද බද්ද අය කරනු ලැබේ."),
    q("මහ නගර සභාවක සභාපතිවරයා හෙවත් නගරාධිපතිවරයා ඉදිරිපත් කරන වාර්ෂික අයවැය ලේඛනය අඛණ්ඩව දෙවරක් සභාවෙන් ප්‍රතික්ෂේප වුවහොත් කුමක් සිදුවේද?", "නගරාධිපතිවරයා ධුරයෙන් ඉල්ලා අස්වූවා සේ සැලකේ", "සභාවේ විපක්ෂ සභිකයන් අත්අඩංගුවට ගැනේ", "වරිපනම් බදු දස ගුණයකින් වැඩි වේ", "අධිකරණය වසා දැමේ", "සභාවේ බහුතර විශ්වාසය අහිමි වී අයවැය දෙවරක් පරාජය වීමෙන් නගරාධිපති/සභාපති ධුරය අහිමි වේ."),
    q("පළාත් පාලන ආයතනයක තීරණ ගැනීමේදී සහාය වීමට පිහිටුවා ඇති ස්ථාවර කාරක සභා (Standing Committees) මොනවාද?", "මුදල්, පොදු වැඩ, සෞඛ්‍ය හා පාරිසරික කාරක සභා", "විදේශ කටයුතු හා යුද කාරක සභා", "අධිකරණ සේවා හා රේගු කමිටු", "මහ බැංකු මුදල් මණ්ඩලය", "විෂය ක්ෂේත්‍ර ගැඹුරින් අධ්‍යයනය කර නිර්දේශ දීමට සභිකයන්ගෙන් ස්ථාවර කමිටු පිහිටුවා ඇත."),
    q("පළාත් පාලන ආයතනවලට පුරවැසියන් වරිපනම් බදු, වෙළඳ ගාස්තු හා ජල බදු නිසි වේලාවට ගෙවීම වැදගත් වන්නේ ඇයි?", "ප්‍රදේශයේ කසළ ඉවත් කිරීම, පාරවල් නඩත්තුව හා පොදු සේවා අඛණ්ඩව පවත්වාගැනීමට", "විදේශ තානාපති කාර්යාල නඩත්තු කිරීමට", "මැතිවරණ කොමිසමට වැටුප් ගෙවීමට", "පෞද්ගලික සමාගම්වලට ලාභ දීමට", "පළාත් පාලන සේවාවන්හි ගුණාත්මකභාවය රඳා පවතින්නේ ප්‍රදේශවාසීන් ගෙවන බදු ආදායම මතය."),
    q("1987ට පෙර ශ්‍රී ලංකාවේ ග්‍රාමීය ප්‍රදේශවල ක්‍රියාත්මක වූ 'සුළු නගර සභා' (Town Councils) සහ 'ගම්සභා' වෙනුවට ඇති කළ ආයතනය කුමක්ද?", "ප්‍රාදේශීය සභා", "මහ නගර සභා", "සෙනෙට් සභා", "රාජ්‍ය මන්ත්‍රණ සභා", "1987 අංක 15 පනතින් පැරණි ගම්සභා හා සුළු නගර සභා ඒකාබද්ධ කර ප්‍රාදේශීය සභා බිහි කෙරිණි."),
    q("නගර සභාවක් හා ප්‍රාදේශීය සභාවක් අතර ඇති ප්‍රධාන වෙනසක් වන්නේ කුමක්ද?", "නගර සභා අර්ධ නාගරික ප්‍රදේශ පාලනය කරන අතර ප්‍රාදේශීය සභා පුළුල් ග්‍රාමීය කොට්ඨාස පාලනය කිරීම", "නගර සභාවල සභිකයන් ඡන්දයෙන් පත් නොවීම", "ප්‍රාදේශීය සභාවල සභාපතිවරයෙකු නොසිටීම", "නගර සභාවලට මුදල් අය කිරීම තහනම් වීම", "ජන ඝනත්වය හා නාගරික ස්වභාවය අනුව නගර සභා (Urban Councils) හා ප්‍රාදේශීය සභා වෙන් කෙරේ."),
    q("මහ නගර සභාවක සභාපති (නගරාධිපති) වෙත මෙන්ම 'නියෝජ්‍ය නගරාධිපතිවරයෙකු' පත් කිරීමේ අරමුණ කුමක්ද?", "නගරාධිපති නොමැති විට රාජකාරි ඉටු කිරීම හා සභා කටයුතුවලට සහාය වීම", "වෙනම පළාත් සභාවක් පිහිටුවීම", "අධිකරණ නඩු විභාග කිරීම", "පොලිස් බලතල පාලනය කිරීම", "නගරාධිපතිගේ නොපැමිණීමේදී පරිපාලනය අඛණ්ඩව පවත්වාගැනීමට නියෝජ්‍ය නගරාධිපති ක්‍රියා කරයි."),
    q("පළාත් පාලන ආයතනයක ඝන අපද්‍රව්‍ය කළමනාකරණය සාර්ථක කර ගැනීමට පුරවැසියන්ට දැක්විය හැකි හොඳම සහයෝගය කුමක්ද?", "දිරන හා නොදිරන කසළ නිවසේදීම වර්ග කර නියමිත දිනවල ලබාදීම", "රාත්‍රී කාලයේ කසළ මහ පාරට විසි කිරීම", "ප්ලාස්ටික් සියල්ල වත්තේ පිළිස්සීම", "කසළ කානු පද්ධතියට දැමීම", "කසළ වර්ගීකරණය මඟින් කොම්පෝස්ට් නිෂ්පාදනය හා ප්‍රතිචක්‍රීකරණය පහසු වී නගරය පිරිසිදු වේ."),
    q("ප්‍රාදේශීය සභාවක හෝ නගර සභාවක රැස්වීම් මහජනතාවට විවෘතව නැරඹීමට ඉඩ දීමෙන් ප්‍රවර්ධනය වන්නේ කුමක්ද?", "ප්‍රාදේශීය ප්‍රජාතන්ත්‍රවාදය හා විනිවිදභාවය", "රාජ්‍ය රහස් හෙළිදරව් වීම", "පක්ෂ කාර්යාල වසා දැමීම", "වරිපනම් බදු අහෝසි වීම", "තම නියෝජිතයන් ගන්නා තීරණ පිළිබඳව ප්‍රදේශවාසීන්ට සෘජුවම අවධානය යොමු කළ හැක."),
    q("පළාත් පාලන මැතිවරණ ක්‍රමය යටතේ 'සභිකයෙකු කොට්ඨාසයකින් සෘජුව තේරී පත්වීම' ජනතාවට ප්‍රයෝජනවත් වන්නේ කෙසේද?", "තම ගමේ පාරක්, කානුවක් හෝ වීදි ලාම්පු ගැටලුවක් ගැන වගකියන නියෝජිතයෙකු සිටීම", "ජනාධිපතිවරයා ඉවත් කිරීමට හැකි වීම", "විදේශ තානාපතිවරුන් පත් කිරීම", "පාර්ලිමේන්තු පනත් අවලංගු කිරීම", "කොට්ඨාස සභිකයා ගමේ ප්‍රශ්න සභාවට ඉදිරිපත් කිරීමට සෘජුවම බැඳී සිටී."),
    q("පළාත් පාලන ආයතනවල අවම වශයෙන් 25%ක කාන්තා නියෝජනයක් තිබීම රටේ ප්‍රජාතන්ත්‍රවාදයට වැදගත් වන්නේ ඇයි?", "ප්‍රජාවේ අඩකට ආසන්න කාන්තාවන්ගේ හා පවුල්වල ගැටලු තීරණ ගැනීමේදී නියෝජනය වීමට", "පිරිමින්ට ඡන්දය දීම නතර කිරීමට", "වෙළඳ බලපත්‍ර අඩු කිරීමට", "පෙරපාසල් වසා දැමීමට", "ජල සැපයුම, මාතෘ සායන හා ප්‍රජා සුබසාධනය වැනි අවශ්‍යතා කෙරෙහි කාන්තා දායකත්වය ඉතා ඵලදායී වේ."),
    q("පළාත් පාලන ආයතනයක සේවය කරන සේවකයන් බඳවා ගැනීම හා විනය පාලනය සාමාන්‍යයෙන් අයත් වන්නේ කාටද?", "පළාත් රාජ්‍ය සේවා කොමිෂන් සභාවට සහ ආයතනික ප්‍රධානීන්ට", "පාසල් විදුහල්පතිවරුන්ට", "ශ්‍රේෂ්ඨාධිකරණ විනිසුරු මණ්ඩලයට", "රේගු දෙපාර්තමේන්තුවට", "පළාත් පාලන සේවයේ කාර්ය මණ්ඩල කළමනාකරණය පළාත් රාජ්‍ය සේවා කොමිසම හරහා සිදු කෙරේ."),
    q("දේශීය හා ප්‍රාදේශීය පාලන ආයතනවල 'මහජන දිනය' පැවැත්වීමේ ප්‍රධාන අරමුණ කුමක්ද?", "ප්‍රදේශවාසීන්ගේ ගැටලු, පැමිණිලි හා යෝජනා සභාපති හා නිලධාරීන් වෙත සෘජුව ඉදිරිපත් කිරීම", "බදු අය කිරීම නතර කිරීම", "මැතිවරණ පැවැත්වීම", "විනිසුරුවරුන් පත් කිරීම", "කඩිනමින් ජනතා ගැටලුවලට විසඳුම් සැපයීමට ප්‍රාදේශීය ලේකම් හා පළාත් පාලන ආයතන මහජන දින පවත්වයි."),
    q("නාගරික ප්‍රදේශවල රථවාහන තදබදය අවම කිරීමට සහ ආදායම් ඉපැයීමට මහ නගර සභා හා නගර සභා පවත්වාගෙන යන සේවාව කුමක්ද?", "පොදු රථගාල් සහ වාහන නැවැත්වීමේ ගාස්තු අය කිරීම", "ජාත්‍යන්තර ගුවන් සේවා මෙහෙයවීම", "දුම්රිය මාර්ග ඉදිකිරීම", "මෝටර් රථ නිෂ්පාදනය කිරීම", "නගර මධ්‍යයේ නියාමනය කළ රථගාල් පවත්වාගෙන යාම නගර පාලනයේ හා ආදායම් ඉපැයීමේ ක්‍රමයකි."),
    q("ප්‍රාදේශීය සභාවක සේවා වපසරිය තුළ 'ග්‍රාමීය පොදු වෙළඳපොළ (සති පොළ)' පවත්වාගෙන යාමෙන් සිදුවන ප්‍රතිලාභය කුමක්ද?", "දේශීය ගොවීන්ට හා වෙළෙන්දන්ට අලෙවි අවස්ථා සැලසීම හා සභාවට බදු ආදායම් ලැබීම", "ආනයනික භාණ්ඩ තහනම් කිරීම", "රේගු ගාස්තු අඩු කිරීම", "මහ බැංකු සංචිත වැඩි කිරීම", "සති පොළවල් ප්‍රාදේශීය ආර්ථිකය සක්‍රීය කරන අතර සභාවට ස්ථිර ආදායමක් උපයා දේ."),
    q("පළාත් පාලන ආයතනවල 'වාර්ෂික මූල්‍ය ප්‍රකාශන විගණනයට ලක් කිරීම' අත්‍යවශ්‍ය වන්නේ ඇයි?", "මහජන බදු මුදල් අවභාවිත වීම වැළැක්වීමට හා වගවීම තහවුරු කිරීමට", "සියලු සභිකයන්ට විදේශ සංචාර දීමට", "අතුරු ව්‍යවස්ථා අවලංගු කිරීමට", "පළාත් සභා වසා දැමීමට", "විගණකාධිපති විගණනය හරහා පළාත් පාලන මූල්‍ය පාලනය විනිවිදභාවයෙන් පවත්වා ගනී."),
    q("මධ්‍යම රජය, පළාත් සභා සහ පළාත් පාලන ආයතන යන ස්ථර තුනම එකම රටක පැවතීම හඳුන්වන්නේ කුමන නමින්ද?", "බහු ස්ථර පාලන ව්‍යුහය (Multi-tier Governance)", "ඒකපුද්ගල ආඥාදායකත්වය", "රාජාණ්ඩු සම්ප්‍රදාය", "හමුදා පරිපාලනය", "ජාතික, පළාත් හා ප්‍රාදේශීය මට්ටම් තුනෙන් රාජ්‍ය සේවා හා නියෝජනය ජනතාවට සමීප කරයි."),
    q("පළාත් පාලන ආයතනයක සීමාව තුළ පවතින ජල මූලාශ්‍ර හා තෙත්බිම් අනවසරයෙන් ගොඩකිරීම වැළැක්වීම සඳහා ගන්නා පියවර කුමක්ද?", "සැලසුම් නොකළ ඉදිකිරීම් තහනම් කර අනුමත සීමා නීති ක්‍රියාත්මක කිරීම", "මැතිවරණ කල් දැමීම", "වරිපනම් බදු නොගෙවා සිටීම", "පුස්තකාල වසා දැමීම", "නාගරික සංවර්ධන අධිකාරිය හා පළාත් පාලන ආයතන පරිසර හිතකාමී භූමි පරිහරණය නියාමනය කරයි."),
    q("ශ්‍රී ලංකාවේ ප්‍රථම කාන්තා නගරාධිපතිනිය ලෙස 2018 දී කොළඹ මහ නගර සභාවට පත්වූයේ කවුද?", "රෝසි සේනානායක", "සිරිමාවෝ බණ්ඩාරනායක", "ඇඩ්ලින් මොලමුරේ", "විමලා විජයවර්ධන", "දේශීය පළාත් පාලන ඉතිහාසයේ කොළඹ ප්‍රථම කාන්තා පුරපතිනිය ලෙස රෝසි සේනානායක පත් විය."),
    q("විමධ්‍යගත පාලනය යටතේ ප්‍රාදේශීය සභාවකට 'ප්‍රජා ශාලා' (Community Halls) ඉදිකිරීමෙන් සිදුවන සමාජීය මෙහෙවර කුමක්ද?", "ගමේ පොදු රැස්වීම්, පුහුණු වැඩමුළු හා සංස්කෘතික කටයුතු සඳහා පොදු අවකාශයක් ලැබීම", "පාර්ලිමේන්තු මැතිවරණ පැවැත්වීම", "විදේශීය බැංකු ශාඛා පිහිටුවීම", "අධිකරණ නඩු විභාග කිරීම", "ප්‍රජා ශාලා ප්‍රදේශයේ සිවිල් සංවිධාන හා තරුණ ක්‍රියාකාරකම් එක්රැස් කරන කේන්ද්‍රස්ථානයකි."),
    q("පළාත් පාලන ආයතනයක සේවාවන් ගුණාත්මක කිරීමට පුරවැසියන්ට ඇති වගකීමක් නොවන්නේ පහත සඳහන් කුමක්ද?", "සභාවේ පොදු ලාම්පු කණු හා බස් නැවතුම්පොළවල් විනාශ කිරීම", "නියමිත වරිපනම් හා බදු ගෙවීම", "කසළ වෙන්කර නිසි ස්ථානවල බැහැර කිරීම", "සභාවේ අඩුපාඩු ගැන නිර්මාණශීලීව පෙන්වා දීම", "පොදු දේපළ ආරක්ෂා කිරීම හා බදු ගෙවීම සෑම ප්‍රදේශවාසියෙකුගේම වගකීමකි."),
    q("නාගරික ප්‍රදේශවල වීදි ආහාර හා ආපනශාලා පරීක්ෂා කර සෞඛ්‍යාරක්ෂිත බව තහවුරු කිරීම සඳහා මහ නගර සභාවල සිටින නිලධාරියා කවුද?", "මහජන සෞඛ්‍ය පරීක්ෂක (PHI)", "තේරීම් භාර නිලධාරී", "ගණකාධිකාරී", "තැපැල් ස්ථානාධිපති", "පළාත් පාලන ආයතනවල මහජන සෞඛ්‍ය පරීක්ෂකවරු ආහාර සුරක්ෂිතතාව හා පරිසර සෞඛ්‍යය අධීක්ෂණය කරති."),
    q("රටේ සියලු පළාත් පාලන ආයතන අතරින් නීතිමය හා පරිපාලන බලතල හා මූල්‍ය ප්‍රතිපාදන වැඩිම ප්‍රමාණයක් ඇති ආයතන වර්ගය කුමක්ද?", "මහ නගර සභා", "ප්‍රාදේශීය සභා", "ග්‍රාමීය සමිති", "සමථ මණ්ඩල", "ප්‍රධාන නාගරික කේන්ද්‍රස්ථාන නියෝජනය කරන මහ නගර සභාවලට පුළුල් වරිපනම් ආදායම් හා බලතල හිමිය."),
    q("ප්‍රාදේශීය සභා පනත අනුව පළාත් පාලන ආයතනයකට ප්‍රදේශයේ පාරිසරික ආරක්ෂාව සඳහා 'හරිත උද්‍යාන හා පැළ තවාන්' පිහිටුවිය හැකිද?", "ඔව්, ප්‍රදේශයේ සෞන්දර්ය හා පරිසර හිතකාමී බව රැකීමට එය සිදු කළ හැක", "නැත, එය විදේශ කටයුතු අමාත්‍යාංශයට පමණක් අයත්ය", "නැත, පළාත් පාලන ආයතනවලට පරිසර බලතල නැත", "නැත, එය ශ්‍රේෂ්ඨාධිකරණය මඟින් කළ යුතුය", "ප්‍රාදේශීය උද්‍යාන, විනෝද ස්ථාන හා රුක් රෝපණය පළාත් පාලන ආයතනවල සුබසාධන කාර්යයන්ට අයත්ය."),
    q("දේශපාලන බලය බෙදාහැරීමේ ක්‍රියාවලිය තුළ පළාත් සභා හා පළාත් පාලන ආයතන අතර සම්බන්ධතාව විස්තර කරන නිවැරදි ප්‍රකාශය කුමක්ද?", "පළාත් සභා විසින් තම පළාතේ පළාත් පාලන ආයතනවලට ප්‍රතිපාදන හා මගපෙන්වීම සැපයීම", "පළාත් පාලන ආයතන පළාත් සභා විසුරුවා හැරීම", "දෙකම එකම ගොඩනැගිල්ලේ පිහිටා තිබීම", "පළාත් සභා විදේශීය රටවල පමණක් තිබීම", "නවවන උපලේඛනයේ I ලැයිස්තුව අනුව පළාත් පාලන ආයතන අධීක්ෂණය හා පහසුකම් සැලසීම පළාත් සභාවට හිමිය."),
    q("විමධ්‍යගත පාලන ව්‍යුහයේදී 'කේන්ද්‍රීය ආණ්ඩුවේ පනත්වලට පටහැනි නොවන පරිදි' පළාත් පාලන අතුරු ව්‍යවස්ථා සෑදීම වැදගත් වන්නේ ඇයි?", "රටේ නීති පද්ධතියේ ඒකාබද්ධතාව හා ඒකීයභාවය ආරක්ෂා වීමට", "පළාත් පාලන ආදායම් නතර කිරීමට", "මැතිවරණ කොමිසම අහෝසි කිරීමට", "අග්‍රාමාත්‍ය ධුරය ඉවත් කිරීමට", "ජාතික නීතිය හා ප්‍රාදේශීය නීති අතර ගැටුම් වැළැක්වීම සඳහා පළාත් අතුරු ව්‍යවස්ථා මූලික නීතියට අනුකූල විය යුතුය."),
    q("ශ්‍රී ලංකාවේ පළාත් පාලන මැතිවරණ ක්‍රමයේ මිශ්‍ර කොට්ඨාස හා සමානුපාතික ලැයිස්තුවට අනුව සභාවක සභාපති තේරෙන්නේ කෙසේද?", "වැඩිම බහුතර ආසන ගත් පක්ෂයේ නාමකරණයෙන් හෝ සභික ඡන්දයෙන්", "දිස්ත්‍රික් ලේකම්ගේ කැමැත්තෙන්", "පොලිස්පතිවරයාගේ නිර්දේශයෙන්", "විගණකාධිපතිගේ පත්වීමෙන්", "තනි පක්ෂයක් 50% ඉක්මවුවහොත් එම පක්ෂ ලේකම්ගේ නම් කිරීමෙන්ද, නැතහොත් සභාවේ පළමු රැස්වීමේ ඡන්දයෙන්ද තෝරයි."),
    q("ප්‍රාදේශීය මට්ටමින් ගංවතුර හා නායයෑම් වැනි හදිසි ආපදාවලදී පළාත් පාලන ආයතන හා ප්‍රාදේශීය ලේකම් කාර්යාල එක්ව ඉටු කරන කාර්යය කුමක්ද?", "සහන කඳවුරු සැපයීම, මාර්ග පිරිසිදු කිරීම හා හදිසි ආධාර බෙදාදීම", "විදේශ ගිවිසුම් අත්සන් කිරීම", "පාර්ලිමේන්තු මැතිවරණ පැවැත්වීම", "නව ව්‍යවස්ථා සම්මත කිරීම", "ආපදා කළමනාකරණයේදී ජනතාවට ආසන්නතම ආයතන ලෙස පළාත් පාලන හා ප්‍රාදේශීය ලේකම් කාර්යාල මූලික වේ."),
    q("පළාත් පාලන ආයතන සතු 'ආදාහනාගාර හා සුසාන භූමි පාලනය, පොදු ස්නානය කළ හැකි ස්ථාන හා පොදු වැසිකිළි නඩත්තුව' මඟින් තහවුරු වන්නේ කුමක්ද?", "ප්‍රජා සෞඛ්‍යය, සනීපාරක්ෂාව සහ ගෞරවනීය නාගරික පරිසරය", "ජාතික ආරක්ෂක හමුදා සංවිධානය", "විදේශීය ආයෝජන නීති", "අධිකරණ සේවා පාලනය", "නාගරික හා ග්‍රාමීය ප්‍රජාවගේ මූලික සනීපාරක්ෂක පහසුකම් සැලසීම පළාත් පාලනයේ ප්‍රධාන වගකීමකි."),
    q("පළාත් සභා සඳහා පවරා ඇති 'පළාත් අධ්‍යාපන පද්ධතිය' තුළ පළාත් පාසල් සංවර්ධනය කිරීම සඳහා ප්‍රමුඛ වගකීම ඇත්තේ කාටද?", "පළාත් අධ්‍යාපන අමාත්‍යාංශයට හා පළාත් අධ්‍යාපන දෙපාර්තමේන්තුවට", "ප්‍රාදේශීය සභා සභාපතිට", "මහ නගර කොමසාරිස්ට", "මහා භාණ්ඩාගාර ලේකම්ට", "ජාතික පාසල් මධ්‍යම අමාත්‍යාංශය යටතේද පළාත් පාසල් පළාත් අධ්‍යාපන අමාත්‍යාංශය යටතේද ක්‍රියාත්මක වේ."),
    q("මහ නගර සභා ආඥාපනත යටතේ පළාත් පාලන ආයතනයක සභිකයෙකු එම ආයතනයේ කොන්ත්‍රාත්තු ලබාගැනීම තහනම් කර ඇත්තේ ඇයි?", "ලැබැඳියාවන් අතර ගැටුම් (Conflict of Interest) හා දූෂණ වැළැක්වීමට", "සභාවේ සභික සංඛ්‍යාව අඩු කිරීමට", "මාර්ග ඉදිකිරීම නතර කිරීමට", "බදු අය කිරීම අහෝසි කිරීමට", "තමන් නියෝජනය කරන සභාවෙන්ම පෞද්ගලික ව්‍යාපාර ලාභ ගැනීම සදාචාර හා නීති විරෝධී වේ."),
    q("ශ්‍රී ලංකාවේ 'ඩොනමෝර් කොමිසම' (1931) හා 'චෝක්සි කොමිසම' පළාත් පාලනය සම්බන්ධයෙන් පොදුවේ අවධාරණය කළ කරුණ කුමක්ද?", "ප්‍රාදේශීය ප්‍රජාතන්ත්‍රවාදය ශක්තිමත් කර පළාත් පාලන ආයතනවල කාර්යක්ෂමතාව වැඩි කිරීම", "සියලු නගර සභා වසා දැමීම", "සර්වජන ඡන්ද බලය අහෝසි කිරීම", "මධ්‍යම රජයට සියලු පාරවල් පැවරීම", "දේශීය පාලන ආයතන ජනතාවට වගකියන ස්වාධීන හා ශක්තිමත් සේවා ආයතන විය යුතු බව නිර්දේශ කෙරිණි."),
    q("සෑම පළාත් පාලන ආයතනයක්ම පවත්වාගෙන යන 'මහජන පැමිණිලි හා තොරතුරු ඒකකය' මඟින් පුරවැසියන්ට හිමිවන අයිතිය කුමක්ද?", "සභාවේ ව්‍යාපෘති, ටෙන්ඩර් හා වියදම් ගැන තොරතුරු දැනගැනීමේ අයිතිය", "සභික වැටුප් තීරණය කිරීමේ අයිතිය", "විනිසුරුවරුන් මාරු කිරීමේ අයිතිය", "රේගු බදු නිදහස් කිරීමේ අයිතිය", "2016 තොරතුරු දැනගැනීමේ පනත යටතේ සෑම මහ නගර, නගර හා ප්‍රාදේශීය සභාවක්ම පොදු අධිකාරියක් ලෙස තොරතුරු දිය යුතුය."),
    q("පළාත් සභා ක්‍රමයේදී ආණ්ඩුව හා පළාත් සභා අතර 'මධ්‍යස්ථ මූල්‍ය සමතුලිතතාව' රැකීම වැදගත් වන්නේ ඇයි?", "පළාත් අතර ආදායම් පරතරය අඩු කර සැමට සමාන පොදු සේවා සැලසීමට", "එක් පළාතක පමණක් පාසල් වැසීමට", "සියලු කර්මාන්තශාලා වසා දැමීමට", "පළාත් පාලන මැතිවරණ අහෝසි කිරීමට", "අඩු බදු ආදායම් ඇති ග්‍රාමීය පළාත්වලටද දියුණු පළාත් මෙන් පහසුකම් ලැබීම ඉන් තහවුරු වේ."),
    q("පළාත් සභා සහ පළාත් පාලන ආයතන මඟින් රටේ ඒකීයභාවයට හා ජාතික සංහිඳියාවට ලැබෙන ප්‍රධාන පිටිවහල කුමක්ද?", "සියලු කලාප හා ජන කොටස්වලට තම ප්‍රදේශයේ පාලනයට සහභාගී වීමේ අවස්ථාව හිමිවීම", "වෙනම රාජ්‍යයන් නවයක් නිර්මාණය වීම", "මධ්‍යම පාර්ලිමේන්තුව අහෝසි වීම", "ජාතික ධජය වෙනස් වීම", "බලය හා සම්පත් ප්‍රාදේශීය ප්‍රජාව සමඟ බෙදාගැනීමෙන් ප්‍රජාතන්ත්‍රවාදී විශ්වාසය හා සමගිය වර්ධනය වේ."),
    q("පළාත් පාලන ආයතනයක සාර්ථකත්වය මැනීමේදී ප්‍රධාන වශයෙන්ම සැලකිල්ලට ගන්නා නිර්ණායකය කුමක්ද?", "ප්‍රදේශයේ පවිත්‍රතාව, මාර්ග තත්ත්වය, කසළ කළමනාකරණය හා ජනතා තෘප්තිය", "සභිකයන් සංඛ්‍යාව සියය ඉක්මවීම", "විදේශ සංචාර ප්‍රමාණය", "ගොඩනැගිලිවල උස ප්‍රමාණය", "පුරවැසියන්ගේ එදිනෙදා ජීවන පහසුකම් ගුණාත්මකව ඉටු කිරීම පළාත් පාලන ආයතනයක සැබෑ කාර්යසාධනයයි."),
    q("ශ්‍රී ලංකාවේ 13 වන ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධනය යටතේ පළාත් සභා ක්‍රමය හඳුන්වා දුන්නේ කුමන වර්ෂයේදීද?", "1987 නොවැම්බර්", "1978 සැප්තැම්බර්", "1972 මැයි", "1948 පෙබරවාරි", "ඉන්දු-ලංකා ගිවිසුමට අනුව පළාත්වලට බලය විමධ්‍යගත කිරීමට 1987 දී 13 වන සංශෝධනය සම්මත කෙරිණි."),
    q("1987 අංක 42 දරන පළාත් සභා පනත යටතේ ශ්‍රී ලංකාව තුළ පිහිටුවා ඇති මුළු පළාත් සභා ගණන කීයද?", "පළාත් සභා 9", "පළාත් සභා 5", "පළාත් සභා 25", "පළාත් සභා 12", "1988 දී තාවකාලිකව ඒකාබද්ධ කළ උතුරු-නැගෙනහිර 2006 ශ්‍රේෂ්ඨාධිකරණ තීන්දුවෙන් වෙන් වූ පසු පළාත් සභා 9ක් පවතී."),
    q("13 වන සංශෝධනයේ නවවන උපලේඛනයේ පළමු ලැයිස්තුව හෙවත් 'පළාත් සභා ලැයිස්තුවට' අයත් වන්නේ කුමන විෂයයන්ද?", "පළාත් අධ්‍යාපනය, සෞඛ්‍ය සේවා, පළාත් මාර්ග, කෘෂිකර්මය හා පළාත් පාලනය", "ආරක්ෂාව, විදේශ කටයුතු හා මුදල් අච්චු ගැසීම", "රේගු බදු හා විදේශ ගමන් බලපත්‍ර", "ජාතික මැතිවරණ හා අගවිනිසුරු පත්වීම", "ව්‍යවස්ථාවේ I ලැයිස්තුවෙන් පළාත් සභාවලට ව්‍යවස්ථාදායක හා විධායක බලය හිමි විෂයයන් දක්වා ඇත."),
    q("නවවන උපලේඛනයේ දෙවන ලැයිස්තුව හෙවත් 'සංවෘත ලැයිස්තුව' (Reserved List) මුළුමනින්ම අයත් වන්නේ කාටද?", "මධ්‍යම රජයට (පාර්ලිමේන්තුවට)", "ප්‍රාදේශීය සභාවලට", "මහ නගර සභාවලට", "පළාත් ආණ්ඩුකාරවරුන්ට", "ජාතික ආරක්ෂාව, විදේශ ප්‍රතිපත්තිය, අධිකරණය, මැතිවරණ හා මුදල් කටයුතු සංවෘත ලැයිස්තුවේ ඇත."),
    q("නවවන උපලේඛනයේ තෙවන ලැයිස්තුව හෙවත් 'සමගාමී ලැයිස්තුවේ' (Concurrent List) විෂයයන් සම්බන්ධයෙන් නීති සෑදීමේ බලය ඇත්තේ කාටද?", "පාර්ලිමේන්තුවට හා පළාත් සභාවලට (උපදේශන ක්‍රියාවලියකින් පසු)", "මහ නගර සභාවලට පමණි", "දිස්ත්‍රික් ලේකම්ට පමණි", "ග්‍රාම නිලධාරීන්ට පමණි", "උසස් අධ්‍යාපනය, නිවාස හා පරිසර ආරක්ෂණය වැනි විෂයයන් දෙපාර්ශ්වයටම පොදුවේ අයත් අතර ගැටුමකදී පාර්ලිමේන්තු නීතිය ප්‍රමුඛ වේ."),
    q("පළාත් සභාවක් විසින් සම්මත කරනු ලබන ප්‍රාදේශීය නීති හඳුන්වන්නේ කුමන නමින්ද?", "ප්‍රඥප්ති (Statutes)", "ආණ්ඩුක්‍රම ව්‍යවස්ථා", "අතුරු ව්‍යවස්ථා (ප්‍රාදේශීය සභා)", "රාජකීය ආඥා", "පළාත් සභාවක් සම්මත කරන ප්‍රඥප්තියක් වලංගු වීම සඳහා පළාත් ආණ්ඩුකාරවරයාගේ අනුමැතිය අවශ්‍ය වේ."),
    q("පළාතක විධායක බලය නාමිකව නියෝජනය කරමින් ජනාධිපතිවරයා විසින් වසර 5කට පත් කරන නිලධාරියා කවුද?", "පළාත් ආණ්ඩුකාරවරයා (Governor)", "ප්‍රධාන අමාත්‍යවරයා", "පළාත් පාලන කොමසාරිස්", "දිස්ත්‍රික් ලේකම්වරයා", "ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ 154ආ වගන්තිය අනුව පළාත් ආණ්ඩුකාරවරයා ජනාධිපතිවරයාගේ නියෝජිතයා වේ."),
    q("පළාත් සභාවේ බහුතර විශ්වාසය දිනාගත් සභිකයා ලෙස පළාතේ සැබෑ දේශපාලන නායකත්වය දරන්නේ කවුද?", "ප්‍රධාන අමාත්‍යවරයා (Chief Minister)", "පළාත් ආණ්ඩුකාරවරයා", "පළාත් ප්‍රධාන ලේකම්", "විගණකාධිපති", "ප්‍රධාන අමාත්‍යවරයාගේ උපදෙස් පරිදි පළාත් අමාත්‍ය මණ්ඩලය (උපරිම 4) ආණ්ඩුකාරවරයා විසින් පත් කරයි."),
    q("පළාත් සභාවක ප්‍රධාන අමාත්‍යවරයාට අමතරව පත් කළ හැකි උපරිම පළාත් අමාත්‍යවරුන් සංඛ්‍යාව කීයද?", "පළාත් අමාත්‍යවරුන් 4", "පළාත් අමාත්‍යවරුන් 15", "පළාත් අමාත්‍යවරුන් 25", "පළාත් අමාත්‍යවරුන් 1", "ව්‍යවස්ථාවේ 154ඊ වගන්තිය අනුව ප්‍රධාන අමාත්‍යවරයා ඇතුළුව පළාත් අමාත්‍ය මණ්ඩලය පස් දෙනෙකුට නොවැඩි විය යුතුය."),
    q("පළාත් සභාවේ සියලු පරිපාලන කටයුතු මෙහෙයවන ඉහළම රාජ්‍ය නිලධාරියා හඳුන්වන්නේ කුමන නමින්ද?", "පළාත් ප්‍රධාන ලේකම් (Chief Secretary)", "නාගරික කොමසාරිස්", "ප්‍රාදේශීය ලේකම්", "කතානායක", "පළාත් රාජ්‍ය සේවයේ ප්‍රධානියා ලෙස ප්‍රධාන ලේකම්වරයා ජනාධිපතිවරයාගේ එකඟතාවයෙන් පත් කෙරේ."),
    q("ශ්‍රී ලංකාවේ පළාත් සභාවක නිල ධුර කාලය කොපමණද?", "වසර 5", "වසර 3", "වසර 6", "වසර 10", "පළාත් සභාව පළමු රැස්වීම පැවැත්වූ දින සිට වසර පහක් ක්‍රියාත්මක වේ."),
    q("පළාත් සභාවකට මූල්‍ය ප්‍රතිපාදන වෙන් කිරීම සඳහා මධ්‍යම රජයට නිර්දේශ ඉදිරිපත් කරන ආයතනය කුමක්ද?", "මුදල් කොමිෂන් සභාව (Finance Commission)", "රාජ්‍ය සේවා කොමිසම", "සමථ මණ්ඩල කොමිසම", "අධිකරණ සේවා කොමිසම", "154ත වගන්තිය යටතේ පිහිටුවා ඇති මුදල් කොමිසම පළාත් අතර සාධාරණ ලෙස අරමුදල් බෙදීම නිර්දේශ කරයි."),
    q("දේශපාලන 'බලය බෙදීම' (Devolution) සහ 'පරිපාලන විමධ්‍යගත කිරීම' (Decentralization) අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "බලය බෙදීමේදී ව්‍යවස්ථාවෙන් තීරණ ගැනීමේ බලය පවරන අතර විමධ්‍යගත කිරීමේදී පරිපාලන කාර්යයන් පමණක් පවරයි", "දෙකම සම්පූර්ණයෙන් එකම අර්ථය දේ", "බලය බෙදීමේදී මැතිවරණ නොපැවැත්වේ", "විමධ්‍යගත කිරීමේදී වෙනම පාර්ලිමේන්තු තනයි", "පළාත් සභා යනු බලය බෙදීමක් වන අතර දිස්ත්‍රික් හා ප්‍රාදේශීය ලේකම් කාර්යාල පරිපාලන විමධ්‍යගත කිරීමකි."),
    q("ශ්‍රී ලංකාවේ පළාත් පාලන ආයතන වර්ග තුන කවරේද?", "මහ නගර සභා, නගර සභා සහ ප්‍රාදේශීය සභා", "පළාත් සභා, අමාත්‍යාංශ සහ කොමිෂන් සභා", "ග්‍රාම නිලධාරී වසම්, කෝරළ සහ පත්තු", "ශ්‍රේෂ්ඨාධිකරණ, මහාධිකරණ සහ මහේස්ත්‍රාත් අධිකරණ", "නාගරික, අර්ධ නාගරික හා ග්‍රාමීය ප්‍රදේශවල ප්‍රාදේශීය සේවා සැපයීමට මෙම ආයතන තුන ක්‍රියා කරයි."),
    q("1987 අංක 15 දරන ප්‍රාදේශීය සභා පනත හඳුන්වා දීමට පෙර ග්‍රාමීය ප්‍රදේශවල ක්‍රියාත්මක වූ පළාත් පාලන ආයතන මොනවාද?", "ගම් සභා (Village Councils) සහ සුළු නගර සභා", "රාජ්‍ය මන්ත්‍රණ සභා", "සෙනෙට් සභාව", "ව්‍යවස්ථාදායක සභාව", "1987 ප්‍රාදේශීය සභා පනතින් ගම් සභා හා සුළු නගර සභා ඒකාබද්ධ කර ප්‍රාදේශීය සභා පිහිටුවන ලදී."),
    q("ශ්‍රී ලංකාවේ ප්‍රථම මහ නගර සභා දෙක වන කොළඹ සහ මහනුවර මහ නගර සභා පිහිටුවනු ලැබුවේ කුමන වර්ෂයේදීද?", "1865 (ක්‍රියාත්මක වූයේ 1866)", "1931", "1948", "1987", "1865 අංක 17 මහ නගර සභා ආඥාපනත යටතේ නවීන පළාත් පාලන ක්‍රමය ශ්‍රී ලංකාවේ ඇරඹිණි."),
    q("මහ නගර සභාවක සභාපතිවරයා හා ප්‍රධාන පරිපාලන නිලධාරියා පිළිවෙළින් කවුරුන්ද?", "නගරාධිපති (Mayor) සහ නාගරික කොමසාරිස් (Municipal Commissioner)", "සභාපති සහ ග්‍රාම නිලධාරී", "ආණ්ඩුකාර සහ ප්‍රධාන ලේකම්", "දිසාපති සහ කතානායක", "මහජන ඡන්දයෙන් නගරාධිපති තේරෙන අතර ස්ථිර රාජ්‍ය සේවකයෙකු නාගරික කොමසාරිස් ලෙස පරිපාලනය කරයි."),
    q("නගර සභාවක සහ ප්‍රාදේශීය සභාවක ප්‍රධානියා හා ස්ථිර පරිපාලන නිලධාරියා පිළිවෙළින් හඳුන්වන්නේ කුමන නමින්ද?", "සභාපති සහ සභා ලේකම්", "නගරාධිපති සහ විගණකාධිපති", "ප්‍රධාන අමාත්‍ය සහ ප්‍රධාන ලේකම්", "මහේස්ත්‍රාත් සහ රෙජිස්ට්‍රාර්", "නගර සභා හා ප්‍රාදේශීය සභාවල දේශපාලන නායකයා සභාපති වන අතර පරිපාලන කටයුතු ලේකම්වරයා මෙහෙයවයි."),
    q("පළාත් පාලන ආයතනයක ධුර කාලය සාමාන්‍යයෙන් කොපමණද?", "වසර 4 (නීතිය අනුව වසර 1කින් දීර්ඝ කිරීමේ බලය විෂය භාර ඇමතිට ඇත)", "වසර 10", "වසර 2", "මාස 6", "නිතිපතා ප්‍රජාතන්ත්‍රවාදී මැතිවරණ පැවැත්වීම මඟින් ප්‍රාදේශීය නියෝජිතයන්ගේ වගවීම රැකේ."),
    q("පළාත් පාලන ආයතනයක් විසින් තම බල ප්‍රදේශය තුළ නීති විරෝධී කසළ දැමීම හෝ වෙළඳපොළ නියාමනය සඳහා පනවන ප්‍රාදේශීය නීති මොනවාද?", "අතුරු ව්‍යවස්ථා (By-laws)", "ආණ්ඩුක්‍රම ව්‍යවස්ථා සංශෝධන", "ජාත්‍යන්තර සම්මුති", "සමථ ගිවිසුම්", "පළාත් සභා අමාත්‍යවරයාගේ අනුමැතිය හා ගැසට් නිවේදනයෙන් පසු පළාත් පාලන අතුරු ව්‍යවස්ථා වලංගු වේ."),
    q("පළාත් පාලන ආයතනවල ප්‍රධානතම දේශීය ආදායම් මාර්ගයක් වන 'වරිපනම් බද්ද' (Assessment Tax / Rates) අය කරන්නේ කුමක් මතද?", "බල ප්‍රදේශයේ පිහිටි නිවාස, ගොඩනැගිලි හා ඉඩම්වල වාර්ෂික තක්සේරු වටිනාකම මත", "පුද්ගලයාගේ විභාග සහතික මත", "විදේශ ගුවන් ටිකට්පත් මත", "ජාතික හැඳුනුම්පත් අංකය මත", "වරිපනම් බදු, වෙළඳ බලපත්‍ර ගාස්තු, සති පොළ ටෙන්ඩර් හා මුද්දර ගාස්තු ප්‍රාදේශීය ආදායම් උපදවයි."),
    q("පළාත් පාලන ආයතනයකට ඉඩම් විකිණීමේදී ගෙවන මුද්දර ගාස්තු හා අධිකරණ දඩ මුදල් ලැබෙන්නේ කෙසේද?", "පළාත් සභාව හරහා රජයෙන් ආපසු පවරා දෙන ආදායම් (Assigned Revenue) ලෙස", "විදේශීය තානාපති කාර්යාලයකින්", "සමථ මණ්ඩලයෙන්", "ලොතරැයි මණ්ඩලයෙන්", "තම බල ප්‍රදේශයේ දේපළ ගනුදෙනු මුද්දර ගාස්තු ආදායමෙන් කොටසක් පළාත් පාලන ආයතනවලට හිමිවේ."),
    q("පළාත් පාලන ආයතනයක අයවැය ලේඛනය වාර්ෂිකව සම්මත නොවුවහොත් හෝ සභාපති ධුරයේ ගැටලුවක් ඇති වුවහොත් ඇතිවිය හැකි තත්ත්වය කුමක්ද?", "විශේෂ කොමසාරිස්වරයෙකු යටතේ පරිපාලනය පවත්වාගෙන යාම හෝ සභාව විසුරුවා හැරීම", "පාර්ලිමේන්තුව විසුරුවා හැරීම", "ශ්‍රේෂ්ඨාධිකරණය වසා දැමීම", "රජයේ බදු අහෝසි කිරීම", "මහජන සේවා අඩාල වීම වැළැක්වීමට පළාත් ආණ්ඩුකාරවරයා විසින් කොමසාරිස්වරයෙකු පත් කළ හැක."),
    q("ශ්‍රී ලංකාවේ 'පරිපාලන දිස්ත්‍රික්ක 25' හි මධ්‍යම රජයේ ඉහළම පරිපාලන සම්බන්ධීකරණ නිලධාරියා කවුද?", "දිස්ත්‍රික් ලේකම් (දිසාපති / District Secretary)", "ප්‍රධාන අමාත්‍යවරයා", "මහ නගරාධිපති", "පළාත් ආණ්ඩුකාරවරයා", "මධ්‍යම රජයේ අමාත්‍යාංශ ව්‍යාපෘති, ඉඩම් හා ආපදා කළමනාකරණය දිස්ත්‍රික් මට්ටමින් දිස්ත්‍රික් ලේකම් සම්බන්ධීකරණය කරයි."),
    q("දිස්ත්‍රික්කයක් තුළ මහජනතාවට හැඳුනුම්පත්, විවාහ ලියාපදිංචිය, විශ්‍රාම වැටුප් හා ඉඩම් බලපත්‍ර වැනි සේවා සපයන කාර්යාලය කුමක්ද?", "ප්‍රාදේශීය ලේකම් කාර්යාලය (Divisional Secretariat)", "සමථ මණ්ඩලය", "මහාධිකරණය", "මැතිවරණ කොමිසම", "ශ්‍රී ලංකාවේ ප්‍රාදේශීය ලේකම් කොට්ඨාස 331ක් පමණ ඇති අතර එහි ප්‍රධානියා ප්‍රාදේශීය ලේකම්වරයාය."),
    q("රාජ්‍ය පරිපාලනයේ ගමේ මට්ටමින් ජනතාවට වඩාත්ම සමීපව සිටින මධ්‍යම රජයේ බිම් මට්ටමේ නිලධාරියා කවුද?", "ග්‍රාම නිලධාරී (Grama Niladhari)", "නාගරික කොමසාරිස්", "විගණකාධිපති", "කැබිනට් ලේකම්", "ඡන්ද හිමි නාමලේඛන සැකසීම, පදිංචි සහතික නිකුත් කිරීම හා ප්‍රාදේශීය තොරතුරු රැස් කිරීම ග්‍රාම නිලධාරී ඉටු කරයි."),
    q("ග්‍රාමීය මට්ටමින් සමාජ සුබසාධන, කෘෂිකාර්මික හා සංවර්ධන කටයුතු සම්බන්ධීකරණය කිරීමට ක්‍රියා කරන අනෙකුත් ක්ෂේත්‍ර නිලධාරීන් කවුද?", "සංවර්ධන නිලධාරී, සමෘද්ධි සංවර්ධන නිලධාරී සහ කෘෂිකර්ම පර්යේෂණ හා නිෂ්පාදන සහකාර", "ශ්‍රේෂ්ඨාධිකරණ විනිසුරුවරුන්", "තානාපතිවරුන්", "විශ්වවිද්‍යාල කුලපතිවරුන්", "මෙම නිලධාරීන් ප්‍රාදේශීය ලේකම් කාර්යාලයට අනුයුක්තව ගමේ සංවර්ධනයට සෘජුව දායක වේ."),
    q("දිස්ත්‍රික්කයක සංවර්ධන ව්‍යාපෘති සමාලෝචනය කිරීම සඳහා පාර්ලිමේන්තු මන්ත්‍රීවරුන්, පළාත් නියෝජිතයන් හා නිලධාරීන් එක්වන රැස්වීම කුමක්ද?", "දිස්ත්‍රික් සම්බන්ධීකරණ කමිටුව (District Coordinating Committee - DCC)", "පාර්ලිමේන්තු තේරීම් කාරක සභාව", "ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාව", "අධිකරණ සේවා කොමිසම", "දිස්ත්‍රික්කයේ සියලු සංවර්ධන කටයුතු සම්බන්ධීකරණය කිරීම DCC හා ප්‍රාදේශීය සම්බන්ධීකරණ කමිටුව (PCC) මඟින් කෙරේ."),
    q("පළාත් පාලන ආයතනයක් විසින් ප්‍රදේශයේ ජනතාවට ලබාදෙන මූලික පොදු සේවාවක් වන්නේ කුමක්ද?", "ප්‍රාදේශීය මාර්ග නඩත්තුව, වීදි ලාම්පු දැල්වීම, කසළ එකතු කිරීම හා මහජන පුස්තකාල පවත්වාගැනීම", "විදේශ ගමන් බලපත්‍ර නිකුත් කිරීම", "හමුදා බඳවා ගැනීම්", "අභියාචනාධිකරණ නඩු ඇසීම", "නගර හා ගම් පිරිසිදුව හා පහසුකම්වලින් යුතුව පවත්වාගැනීම පළාත් පාලන ආයතනවල එදිනෙදා කාර්යයයි."),
    q("ප්‍රාදේශීය සභාවක් තුළ පෙර පාසල් (මුල් ළමාවිය සංවර්ධන මධ්‍යස්ථාන), මාතෘ සායන ගොඩනැගිලි හා ක්‍රීඩාපිටි පවත්වාගෙන යන්නේ කුමන අරමුණින්ද?", "ප්‍රාදේශීය ප්‍රජාවගේ අධ්‍යාපන, සෞඛ්‍ය හා සමාජ සුබසාධනය නැංවීමට", "විදේශ ආදායම් බදු අය කිරීමට", "මහාධිකරණ පිහිටුවීමට", "රාජ්‍ය රහස් රැකීමට", "ජනතාවගේ ජීවන තත්ත්වය ඉහළ නැංවීම සඳහා පළාත් පාලන ආයතන සමාජ සුබසාධන සේවා ක්‍රියාත්මක කරයි."),
    q("නාගරික ප්‍රදේශයක ගොඩනැගිල්ලක් ඉදිකිරීමට පෙර අදාළ මහ නගර සභාවෙන් හෝ නගර සභාවෙන් ලබාගත යුතු අනිවාර්ය අනුමැතිය කුමක්ද?", "ගොඩනැගිලි සැලසුම් අනුමැතිය සහ අනුකූලතා සහතිකය (COC)", "විදේශ ගමන් බලපත්‍රය", "ඡන්ද හිමි නාමලේඛනය", "විවාහ සහතිකය", "නාගරික සැලසුම්කරණය, කානු පද්ධති අවහිර නොවීම හා ආරක්ෂාව රැකීමට ගොඩනැගිලි සැලසුම් අනුමත කළ යුතුය."),
    q("පළාත් සභා ක්‍රමයේදී 'පළාත් රාජ්‍ය සේවා කොමිෂන් සභාව' ඉටු කරන කාර්යය කුමක්ද?", "පළාත් රාජ්‍ය සේවයට නිලධාරීන් බඳවා ගැනීම, උසස් කිරීම, ස්ථාන මාරු කිරීම හා විනය පාලනය", "පාර්ලිමේන්තු මැතිවරණ පැවැත්වීම", "ජාතික මුදල් අච්චු ගැසීම", "විදේශ තානාපතිවරුන් පත් කිරීම", "පළාතේ ගුරුවරුන් හා පළාත් පරිපාලන නිලධාරීන්ගේ සේවා කටයුතු පළාත් රාජ්‍ය සේවා කොමිසම යටතේ සිදුවේ."),
    q("13 වන ව්‍යවස්ථා සංශෝධනය අනුව කිසියම් පළාත් සභාවක් ආණ්ඩුක්‍රම ව්‍යවස්ථාවට අනුකූලව පවත්වාගෙන යාමට අපොහොසත් වුවහොත් ජනාධිපතිවරයාට ගත හැකි පියවර කුමක්ද?", "154ඇ වගන්තිය යටතේ පළාත් සභාවේ බලතල තාවකාලිකව තමා යටතට ගැනීම හෝ පාර්ලිමේන්තුවට පැවරීම", "ශ්‍රී ලංකා ආණ්ඩුක්‍රම ව්‍යවස්ථාව සම්පූර්ණයෙන් අහෝසි කිරීම", "අග්‍රාමාත්‍ය ධුරය අහෝසි කිරීම", "මහ බැංකුව වසා දැමීම", "රටේ ඒකීයභාවය හා නීතිමය පාලනය අඛණ්ඩව රැකගැනීම සඳහා මෙම හදිසි ප්‍රතිපාදනය ව්‍යවස්ථාවේ දක්වා ඇත."),
    q("විමධ්‍යගත පාලන ක්‍රමයේ ඇති ප්‍රධානතම ප්‍රජාතන්ත්‍රවාදී වාසිය කුමක්ද?", "ප්‍රාදේශීය ජනතාවගේ අවශ්‍යතා හොඳින්ම දන්නා ඔවුන්ගේම නියෝජිතයන් විසින් ඉක්මනින් තීරණ ගැනීම", "සෑම කුඩා ගැටලුවකටම කොළඹට යාමට සිදුවීම", "මහජන ඡන්ද අවශ්‍ය නොවීම", "ව්‍යවස්ථා සභාව වසා දැමීම", "ප්‍රාදේශීය නායකත්වය පුහුණු වීමත් ජනතා සහභාගිත්වය වැඩි වීමත් ඉන් සිදුවේ."),
    q("පළාත් සභාවක සැසිවාරවල සභාපතිත්වය දරමින් විවාද මෙහෙයවන්නේ කවුද?", "පළාත් සභාවේ සභාපතිවරයා (Chairman) සහ උප සභාපතිවරයා", "මධ්‍යම පාර්ලිමේන්තුවේ කතානායක", "ශ්‍රේෂ්ඨාධිකරණ අගවිනිසුරු", "විගණකාධිපතිවරයා", "පළාත් සභා සභිකයන් අතරින් ඡන්දයෙන් තේරී පත්වන සභාපතිවරයා සභා රැස්වීම්වල විනය රකී."),
    q("පළාත් පාලන මැතිවරණ පැවැත්වීමේදී 2017 වසරේ හඳුන්වා දුන් නව 'මිශ්‍ර සමානුපාතික ක්‍රමය' යටතේ සභිකයන් තෝරන්නේ කුමන අනුපාතයකින්ද?", "60% කොට්ඨාස (බහුතර ඡන්ද) මට්ටමෙන් හා 40% සමානුපාතික ලැයිස්තුවෙන්", "100% ජාතික ලැයිස්තුවෙන් පමණි", "90% පත් කළ මන්ත්‍රීවරුන් ලෙස", "50% රාජ්‍ය නිලධාරීන් ලෙස", "සෑම කොට්ඨාසයකටම වගකියන මන්ත්‍රීවරයෙකු බිහිකිරීමත් කුඩා පක්ෂ හා කාන්තා නියෝජනය රැකීමත් මෙහි අරමුණ විය."),
    q("මහ නගර සභාවක් හෝ ප්‍රාදේශීය සභාවක් විසින් ක්‍රියාත්මක කරන 'මහජන පුස්තකාල හා ප්‍රජා ශාලා' මඟින් සමාජයට සැලසෙන සේවාව කුමක්ද?", "සියලු වයස්වල පුරවැසියන්ට නොමිලේ කියවීමේ හා දැනුම බෙදාගැනීමේ අවස්ථා සැලසීම", "රේගු බදු එකතු කිරීම", "විදේශ ගමන් බලපත්‍ර මුද්‍රණය කිරීම", "විනිසුරුවරුන් පුහුණු කිරීම", "ප්‍රජා අධ්‍යාපනය හා යහපත් විවේක කාල සංස්කෘතියක් ගොඩනැගීමට පළාත් පාලන පුස්තකාල විශාල මෙහෙයක් ඉටු කරයි."),
    q("පළාත් සභාවක ගිණුම් පරීක්ෂා කර මූල්‍ය විනය තහවුරු කිරීම සඳහා පවතින පාර්ලිමේන්තු මට්ටමේ අධීක්ෂණ ව්‍යුහය කුමක්ද?", "විගණකාධිපතිවරයාගේ විගණනය හා පළාත් සභා ගිණුම් කාරක සභාව", "වෙළඳසැල් හිමියන්ගේ සංගමය", "සමථ මණ්ඩල සභාව", "විදේශ කටයුතු කමිටුව", "මහජන මුදල් අවභාවිත නොවීමට විගණකාධිපති දෙපාර්තමේන්තුව පළාත් සභා හා පළාත් පාලන ආයතනද විගණනය කරයි."),
    q("පළාත් පාලන ආයතන තුළ 'වීදි සුනඛයන් පාලනය, වසංගත රෝග මර්දනය හා ඩෙංගු මදුරු කීට මර්දනය' සිදු කරන්නේ කාගේ වගකීමක් ලෙසද?", "පළාත් පාලන ආයතනයේ සෞඛ්‍ය අංශයේ සහ මහජන සෞඛ්‍ය පරීක්ෂකවරුන්ගේ", "මැතිවරණ කොමිසමේ", "විගණකාධිපතිවරයාගේ", "පාර්ලිමේන්තු මහලේකම්ගේ", "ප්‍රදේශයේ පාරිසරික සෞඛ්‍ය හා බෝවන රෝග වැළැක්වීම පළාත් පාලන ආයතනවල ප්‍රධාන වගකීමකි."),
    q("පළාත් සභාවක් නොමැති අවස්ථාවක (නිල කාලය අවසන් වී මැතිවරණ පැවැත්වෙන තුරු) පළාත් පාලන ආයතන හා පළාත් පරිපාලනය ක්‍රියාත්මක වන්නේ කා යටතේද?", "පළාත් ආණ්ඩුකාරවරයා සහ පළාත් ප්‍රධාන ලේකම් යටතේ", "වෙනත් රටක තානාපතිවරයා යටතේ", "පෞද්ගලික සමාගම් යටතේ", "විශ්වවිද්‍යාල ශිෂ්‍ය සංගම් යටතේ", "පළාත් සභාව විසුරුවා හැර ඇති විට ආණ්ඩුකාරවරයා ප්‍රධාන ලේකම් හරහා අඛණ්ඩ සේවා පවත්වාගනී."),
    q("ශ්‍රී ලංකාවේ 'පළාත් පාලන දෙපාර්තමේන්තුව' හා 'පළාත් පාලන කොමසාරිස්' ඉටු කරන කාර්යභාරය කුමක්ද?", "පළාත තුළ පිහිටි ප්‍රාදේශීය සභා, නගර සභා හා මහ නගර සභා පරිපාලනය අධීක්ෂණය හා මගපෙන්වීම", "ජාතික ආරක්ෂක හමුදා මෙහෙයවීම", "රේගු බදු පැනවීම", "නඩු තීන්දු ලිවීම", "පළාත් පාලන ආයතන නීත්‍යානුකූලව හා කාර්යක්ෂමව පවත්වාගැනීමට පළාත් පාලන කොමසාරිස් සහාය වේ."),
    q("පළාත් පාලන ආයතනයක 'ප්‍රජා ජල ව්‍යාපෘති, සතිපොළවල්, බස් නැවතුම්පොළ හා පොදු වෙළඳසැල්' නඩත්තු කිරීමෙන් ලැබෙන ප්‍රතිලාභය කුමක්ද?", "ග්‍රාමීය හා නාගරික ආර්ථික කටයුතු පහසු වී සභාවටද ස්ථිර ආදායමක් ලැබීම", "වෙළඳාම සම්පූර්ණයෙන් නැවැත්වීම", "ප්‍රවාහන සේවා අඩාල වීම", "ජනතාව ගමෙන් පලා යාම", "පොදු යටිතල පහසුකම් ප්‍රාදේශීය වෙළඳපොළ හා සේවා ආර්ථිකය ශක්තිමත් කරයි."),
    q("විමධ්‍යගත පාලනය යටතේ 'ප්‍රාදේශීය සභාවක ස්ථාවර කමිටු' (මුදල්, නිවාස හා සෞඛ්‍ය කමිටු වැනි) පිහිටුවීම වැදගත් වන්නේ ඇයි?", "පක්ෂ විපක්ෂ සියලු සභිකයන්ගේ විශේෂඥ අදහස් ලබාගෙන ප්‍රාදේශීය තීරණ වැඩිදියුණු කිරීමට", "සභා රැස්වීම් නැවැත්වීමට", "සභිකයන් අතර ගැටුම් වැඩි කිරීමට", "අයවැය සැඟවීමට", "කමිටු ක්‍රමය හරහා සභාවේ වැඩකටයුතු විධිමත්ව පරීක්ෂා කර ක්‍රියාත්මක කළ හැකිය."),
    q("පළාත් සභා සහ මධ්‍යම රජය අතර 'අධිකරණ බලය' (Judicial Power) බෙදා ඇති ආකාරය කුමක්ද?", "අධිකරණ බලය විමධ්‍යගත නොකර එක් ජාතික අධිකරණ පද්ධතියක් යටතේ තබා ගැනීම", "සෑම ප්‍රාදේශීය සභාවකටම වෙනම ශ්‍රේෂ්ඨාධිකරණයක් පිහිටුවීම", "පළාත් සභා විසින් අගවිනිසුරු පත් කිරීම", "පොලිසිය අධිකරණ වසා දැමීම", "ඒකීය රාජ්‍ය ව්‍යුහය තුළ යුක්තිය පසිඳලීම රට පුරාම එක් ඒකාබද්ධ අධිකරණ පද්ධතියකින් ඉටු කෙරේ."),
    q("ප්‍රාදේශීය පාලනය තුළ පුරවැසියන් හට තම පළාත් පාලන ආයතනයේ ක්‍රියාකාරිත්වයට සහභාගි විය හැකි ප්‍රායෝගික ක්‍රමයක් කුමක්ද?", "මහජන සභා රැස්වීම්, පෙත්සම් ඉදිරිපත් කිරීම, මාර්ගගත පැමිණිලි හා ප්‍රජා උපදේශන කමිටු", "කසළ පාරේ දැමීම", "වරිපනම් බදු නොගෙවා සිටීම", "වීදි ලාම්පු කැඩීම", "විමසිලිමත් පුරවැසියන්ගේ සහභාගිත්වය ප්‍රාදේශීය පාලනයේ වගවීම හා ගුණාත්මක බව ඉහළ නංවයි."),
    q("1973 දී ශ්‍රී ලංකාවේ හඳුන්වා දුන් 'දිස්ත්‍රික් දේශපාලන අධිකාරිය' හා 1980 'දිස්ත්‍රික් සංවර්ධන සභා' පිහිටුවීමේ ප්‍රධාන අරමුණ කුමක් වීද?", "දිස්ත්‍රික් මට්ටමින් සංවර්ධන සැලසුම් සකස් කර පරිපාලනය විමධ්‍යගත කිරීම", "පාර්ලිමේන්තුව වසා දැමීම", "විදේශීය පාලනය යළි ගෙන ඒම", "මැතිවරණ කොමිසම අහෝසි කිරීම", "1987 පළාත් සභා ක්‍රමයට පෙර ශ්‍රී ලංකාව අත්හදා බැලූ ප්‍රාදේශීය විමධ්‍යගත පියවරයන් ලෙස මේවා සැලකේ."),
    q("පළාත් පාලන ආයතනයකට 'ප්‍රමාණවත් මූල්‍ය ස්වාධීනත්වයක්' තිබීම වැදගත් වන්නේ ඇයි?", "මධ්‍යම රජයේ ප්‍රතිපාදන මත පමණක් නොරැඳී ප්‍රදේශයේ හදිසි අවශ්‍යතා සඳහා ඉක්මනින් සේවා සැලසීමට", "සභිකයන්ට පමණක් තෑගි බෙදාදීමට", "රජයේ බදු සම්පූර්ණයෙන් නැවැත්වීමට", "මාර්ග අලුත්වැඩියා නොකිරීමට", "ස්වයං ආදායම් මාර්ග දියුණු වූ පළාත් පාලන ආයතනවලට ජනතා අවශ්‍යතා ඉක්මනින් ඉටු කළ හැකිය."),
    q("නාගරික හා ප්‍රාදේශීය කසළ කළමනාකරණයේදී වර්තමානයේ පළාත් පාලන ආයතන දිරිගන්වන තිරසාර ක්‍රමවේදය කුමක්ද?", "මූලාශ්‍රයේදී කසළ වර්ග කර කොම්පෝස්ට් පොහොර නිෂ්පාදනය හා ප්‍රතිචක්‍රීකරණය කිරීම", "සියලු කසළ ගංගාවලට දැමීම", "පාර අයිනේ ප්ලාස්ටික් පිළිස්සීම", "කසළ එකතු කිරීම සම්පූර්ණයෙන් නැවැත්වීම", "හරිත කසළ කළමනාකරණය පරිසර දූෂණය අඩු කර සභාවට අමතර ආදායමක්ද ගෙන දෙයි."),
    q("විමධ්‍යගත පාලන ව්‍යුහය තුළ 'ග්‍රාමීය යටිතල පහසුකම්' සංවර්ධනය කිරීමෙන් ජාතික ආර්ථිකයට සිදුවන යහපත කුමක්ද?", "ගොවි නිෂ්පාදන නගරයට ගෙන යාම පහසු වී නාගරික ජනගහන තදබදය හා ප්‍රාදේශීය දිළිඳුකම අඩු වීම", "ග්‍රාමීය පාසල් වැසී යාම", "කෘෂිකර්මාන්තය නතර වීම", "නගරවල වෙළඳාම අඩාල වීම", "ගම හා නගරය අතර සමබර සංවර්ධනය රටේ සමස්ත ආර්ථික ස්ථාවරත්වයට අත්‍යවශ්‍යය."),
    q("පළාත් සභා ක්‍රමය යටතේ පනවන ප්‍රඥප්තියක් ව්‍යවස්ථාවට පටහැනිදැයි පරීක්ෂා කිරීමේදී ආණ්ඩුකාරවරයාට එය යොමු කළ හැක්කේ කුමන ආයතනයටද?", "ශ්‍රේෂ්ඨාධිකරණය වෙත (ජනාධිපතිවරයා හරහා)", "ප්‍රාදේශීය සභා සභාපති වෙත", "සමථ මණ්ඩලය වෙත", "මහ බැංකුව වෙත", "ව්‍යවස්ථාපිත උත්තරීතරභාවය රැකීම සඳහා පළාත් ප්‍රඥප්ති පිළිබඳ ව්‍යවස්ථානුකූලභාවය ශ්‍රේෂ්ඨාධිකරණය විසින් තීරණය කරයි."),
    q("පළාත් පාලන ආයතන ප්‍රජාතන්ත්‍රවාදයේ 'තොටිල්ල' (Cradle of Democracy) ලෙස හඳුන්වන්නේ ඇයි?", "පුරවැසියන්ට පාලනයට සෘජුවම සම්බන්ධ වීමට හා අනාගත ජාතික නායකයන් පුහුණු වීමට මුල්ම අවස්ථාව සලසන බැවිනි", "එහි මැතිවරණ කිසිදා නොපවත්වන බැවිනි", "පාසල් දරුවන්ට පමණක් ඡන්ද බලය ඇති බැවිනි", "ඒවා රාජාණ්ඩු ක්‍රම නිසා", "ගමේ හා නගරයේ ප්‍රජාතන්ත්‍රවාදී අත්දැකීම් ශක්තිමත් ජාතික ප්‍රජාතන්ත්‍රවාදයකට පදනම දමයි."),
    q("ශ්‍රී ලංකාවේ ඒකීය රාජ්‍ය ව්‍යුහය තුළ පළාත් සභා හා පළාත් පාලන ආයතන සමඟිව ක්‍රියා කිරීමෙන් තහවුරු වන්නේ කුමක්ද?", "සැමට සමාන සේවා ලැබෙන, ජනතාවට වගකියන සමබර හා කාර්යක්ෂම රාජ්‍ය පාලනයක්", "රට කැබලි නවයකට වෙන් වීම", "පාර්ලිමේන්තුව අහෝසි වීම", "මහජන ඡන්දය අවශ්‍ය නොවීම", "මධ්‍යම ආණ්ඩුව, පළාත් සභා සහ පළාත් පාලන ආයතන සහයෝගයෙන් ක්‍රියා කිරීම සංවර්ධනය වේගවත් කරයි.")
  )
}

